# Candidate-independent autonomy facts plus a few criterion-specific positive cases.
def autonomy_outcome(candidate_id: str, scenario_id: str) -> str:
    if scenario_id in {"S13","S29"}:
        return A_SHADOW
    if scenario_id == "S28":
        return A_FAIL
    if scenario_id == "S20":
        return A_NT
    if scenario_id == "S08" and candidate_id in {"TS-03","TS-05","TS-06","TS-07"}:
        return A_NT
    if scenario_id == "S18":
        return A_YES
    if scenario_id == "S17" and candidate_id in {"TS-04","TS-05","TS-06","TS-09"}:
        return A_YES
    return A_UND


def recognition_outcome(mode: str, scenario_id: str) -> str:
    determinate, indeterminate = RECOGNITION_SETS[mode]
    if scenario_id in determinate:
        return R_YES
    if scenario_id in indeterminate:
        return R_UND
    return R_NONE

